	if result.RunID != "" {
		fmt.Fprintf(deps.stdout, "Run: %s counts=%d/%d passed failed=%d errors=%d duration=%s\n", result.RunID, result.Counts.Passed, result.Counts.Total, result.Counts.Failed, result.Counts.Errors, result.Duration)
	}
	if result.Artifact != "" {
